package ma.lias.entity;
import jakarta.persistence.*; import java.time.LocalDate;
@Entity @Table(name="team_chiefs")
public class TeamChief { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="mandate_id") private Long mandateId; @Column(name="member_id") private Long memberId; @Column(name="team_id") private Long teamId; @Column(name="start_date") private LocalDate startDate; @Column(name="end_date") private LocalDate endDate; public Long getId(){return id;} public void setId(Long id){this.id=id;} public Long getMandateId(){return mandateId;} public void setMandateId(Long mandateId){this.mandateId=mandateId;} public Long getMemberId(){return memberId;} public void setMemberId(Long memberId){this.memberId=memberId;} public Long getTeamId(){return teamId;} public void setTeamId(Long teamId){this.teamId=teamId;} public LocalDate getStartDate(){return startDate;} public void setStartDate(LocalDate startDate){this.startDate=startDate;} public LocalDate getEndDate(){return endDate;} public void setEndDate(LocalDate endDate){this.endDate=endDate;} }
